using System.Globalization;
using System.Security.Claims;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using MadaAcademy.Api.Persistence;
using MadaAcademy.Api.Persistence.Entities;
using Microsoft.EntityFrameworkCore;

namespace MadaAcademy.Api.Modules.Operations;

public static class EnrollmentBulkImportEndpoints
{
    private const long MaxBytes = 5 * 1024 * 1024;
    private static readonly TimeSpan PreviewLifetime = TimeSpan.FromHours(24);
    private const string PreviewAction = "BULK_IMPORT_ENROLLMENT_PREVIEW_CREATED";
    private const string CommitAction = "BULK_IMPORT_ENROLLMENT_COMMITTED";

    public static IEndpointRouteBuilder MapMadaEnrollmentBulkImportEndpoints(this IEndpointRouteBuilder endpoints)
    {
        var api = endpoints.MapGroup("/api/v1/imports/enrollments").RequireAuthorization("staff");
        api.MapPost("/csv/preview", PreviewAsync);
        api.MapPost("/commit", CommitAsync);
        return endpoints;
    }

    private static async Task<IResult> PreviewAsync(HttpRequest request, ClaimsPrincipal user, MadaDbContext db, CancellationToken ct)
    {
        if (!CanImport(user) || !TryScope(user, out var tenantId, out var branchScope)) return Error(403, "IMPORT_FORBIDDEN", "Only branch managers and secretaries can import enrollments.");
        var upload = await ReadUpload(request, ct); if (upload.Error is not null) return upload.Error;
        var rows = Parse(upload.Bytes!, out var parseErrors); if (parseErrors.Count > 0) return Validation(parseErrors); if (rows.Length is 0 or > 1000) return Error(400, "ROW_LIMIT", "CSV must contain 1 to 1000 rows.");
        var studentIds = rows.Select(x => x.StudentId).Distinct().ToArray(); var offeringIds = rows.Select(x => x.OfferingId).Distinct().ToArray();
        var students = await db.Students.AsNoTracking().Where(x => x.TenantId == tenantId && x.Status == "ACTIVE" && studentIds.Contains(x.Id)).ToDictionaryAsync(x => x.Id, ct);
        var offerings = await db.CourseOfferings.AsNoTracking().Where(x => x.TenantId == tenantId && x.Status != "ARCHIVED" && x.Status != "CANCELLED" && offeringIds.Contains(x.Id)).ToDictionaryAsync(x => x.Id, ct);
        var existing = await db.StudentEnrollments.AsNoTracking().Where(x => offeringIds.Contains(x.CourseOfferingId) && studentIds.Contains(x.StudentId) && (x.Status == "ACTIVE" || x.Status == "WAITLISTED")).Select(x => new { x.StudentId, x.CourseOfferingId }).ToListAsync(ct);
        var occupied = await db.StudentEnrollments.AsNoTracking().Where(x => offeringIds.Contains(x.CourseOfferingId) && x.Status == "ACTIVE").GroupBy(x => x.CourseOfferingId).Select(x => new { OfferingId = x.Key, Count = x.Count() }).ToDictionaryAsync(x => x.OfferingId, x => x.Count, ct);
        var duplicateKeys = existing.Select(x => Key(x.StudentId, x.CourseOfferingId)).ToHashSet(); var batchKeys = new HashSet<string>(); var preview = new List<EnrollmentPreviewRow>();
        for (var i = 0; i < rows.Length; i++)
        {
            var row = rows[i]; var errors = new List<string>(); var key = Key(row.StudentId, row.OfferingId); var status = "WAITLISTED";
            if (!students.TryGetValue(row.StudentId, out var student)) errors.Add("studentId is not an active student in this academy.");
            if (!offerings.TryGetValue(row.OfferingId, out var offering)) errors.Add("courseOfferingId is not an active group in this academy.");
            if (student is not null && offering is not null && student.BranchId != offering.BranchId) errors.Add("student and group must belong to the same branch.");
            if (branchScope.HasValue && ((student is not null && student.BranchId != branchScope.Value) || (offering is not null && offering.BranchId != branchScope.Value))) errors.Add("row is outside the authenticated branch scope.");
            if (row.Price < 0) errors.Add("finalPricePiastres cannot be negative.");
            if (!batchKeys.Add(key) || duplicateKeys.Contains(key)) errors.Add("student is already active or waitlisted in this group, or appears twice in this batch.");
            if (errors.Count == 0 && offering is not null) { var current = occupied.GetValueOrDefault(offering.Id); status = current < offering.MaxStudents ? "ACTIVE" : "WAITLISTED"; if (status == "ACTIVE") occupied[offering.Id] = current + 1; }
            preview.Add(new EnrollmentPreviewRow(i + 1, row.StudentId, row.OfferingId, row.Price, status, errors.Count == 0 ? "CREATE" : "REVIEW", errors));
        }
        var source = MakeSource(upload.Bytes!, upload.Name!); var id = Guid.NewGuid(); var hash = Hash(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(preview)));
        db.AuditEvents.Add(new AuditEvent { ActorUserId = Actor(user), TenantId = tenantId, BranchId = branchScope, Action = PreviewAction, TargetType = "BULK_IMPORT_ENROLLMENT_PREVIEW", TargetId = id.ToString(), Reason = "Enrollment CSV preview created; no enrollments or invoices were written.", MetadataJson = JsonSerializer.Serialize(new StoredEnrollmentPreview(id, hash, "PREVIEWED", preview, source)) }); await db.SaveChangesAsync(ct);
        return Results.Ok(new { data = new { previewId = id, previewHash = hash, rows = preview, activeCount = preview.Count(x => x.Action == "CREATE" && x.Status == "ACTIVE"), waitlistedCount = preview.Count(x => x.Action == "CREATE" && x.Status == "WAITLISTED"), sourceFile = source, state = "PREVIEW_ONLY" } });
    }

    private static async Task<IResult> CommitAsync(EnrollmentCommitRequest request, ClaimsPrincipal user, MadaDbContext db, CancellationToken ct)
    {
        if (!CanImport(user) || !TryScope(user, out var tenantId, out var branchScope)) return Error(403, "IMPORT_FORBIDDEN", "Only branch managers and secretaries can import enrollments.");
        var audit = await db.AuditEvents.SingleOrDefaultAsync(x => x.TenantId == tenantId && x.Action == PreviewAction && x.TargetId == request.PreviewId.ToString(), ct); if (audit?.MetadataJson is null) return Error(404, "PREVIEW_NOT_FOUND", "Enrollment preview was not found."); if (branchScope.HasValue && audit.BranchId != branchScope) return Error(403, "BRANCH_SCOPE_DENIED", "The preview is outside the authenticated branch scope."); var stored = JsonSerializer.Deserialize<StoredEnrollmentPreview>(audit.MetadataJson); if (stored is null || stored.PreviewId != request.PreviewId || !FixedHash(stored.Hash, request.PreviewHash)) return Error(409, "PREVIEW_HASH_MISMATCH", "The supplied preview hash does not match the stored preview."); if (stored.Source.ExpiresAt <= DateTimeOffset.UtcNow) return Error(410, "PREVIEW_EXPIRED", "The enrollment preview expired."); if (request.SourceFile is null || stored.Source.Name != request.SourceFile.Name || stored.Source.Size != request.SourceFile.Size || !FixedHash(stored.Source.Hash, request.SourceFile.Hash)) return Error(409, "SOURCE_FILE_MISMATCH", "The source file identity does not match."); if (stored.Rows.Any(x => x.Action != "CREATE")) return Error(409, "PREVIEW_REQUIRES_REVIEW", "Resolve every REVIEW row before committing."); if (await db.AuditEvents.AnyAsync(x => x.TenantId == tenantId && x.Action == CommitAction && x.TargetId == request.PreviewId.ToString(), ct)) return Error(409, "PREVIEW_ALREADY_COMMITTED", "This preview has already been committed.");
        var studentIds = stored.Rows.Select(x => x.StudentId).Distinct().ToArray(); var offeringIds = stored.Rows.Select(x => x.OfferingId).Distinct().ToArray(); var students = await db.Students.Where(x => x.TenantId == tenantId && x.Status == "ACTIVE" && studentIds.Contains(x.Id)).ToDictionaryAsync(x => x.Id, ct); var offerings = await db.CourseOfferings.Where(x => x.TenantId == tenantId && x.Status != "ARCHIVED" && x.Status != "CANCELLED" && offeringIds.Contains(x.Id)).ToDictionaryAsync(x => x.Id, ct); var existing = await db.StudentEnrollments.Where(x => studentIds.Contains(x.StudentId) && offeringIds.Contains(x.CourseOfferingId) && (x.Status == "ACTIVE" || x.Status == "WAITLISTED")).Select(x => new { x.StudentId, x.CourseOfferingId }).ToListAsync(ct); if (stored.Rows.Any(x => !students.ContainsKey(x.StudentId) || !offerings.ContainsKey(x.OfferingId) || students[x.StudentId].BranchId != offerings[x.OfferingId].BranchId || (branchScope.HasValue && offerings[x.OfferingId].BranchId != branchScope.Value)) || existing.Count > 0) return Error(409, "PREVIEW_STALE", "A student, group, or duplicate enrollment changed after preview.");
        var occupied = await db.StudentEnrollments.Where(x => offeringIds.Contains(x.CourseOfferingId) && x.Status == "ACTIVE").GroupBy(x => x.CourseOfferingId).Select(x => new { OfferingId = x.Key, Count = x.Count() }).ToDictionaryAsync(x => x.OfferingId, x => x.Count, ct); var enrollments = new List<StudentEnrollment>(); foreach (var row in stored.Rows) { var offering = offerings[row.OfferingId]; var status = occupied.GetValueOrDefault(offering.Id) < offering.MaxStudents ? "ACTIVE" : "WAITLISTED"; if (status != row.Status) return Error(409, "PREVIEW_STALE", "Group capacity changed after preview; create a fresh preview."); enrollments.Add(new StudentEnrollment { StudentId = row.StudentId, CourseOfferingId = row.OfferingId, FinalPricePiastres = row.Price, Status = status }); if (status == "ACTIVE") occupied[offering.Id]++; } db.StudentEnrollments.AddRange(enrollments); db.AuditEvents.Add(new AuditEvent { ActorUserId = Actor(user), TenantId = tenantId, BranchId = branchScope, Action = CommitAction, TargetType = "BULK_IMPORT_ENROLLMENT_PREVIEW", TargetId = request.PreviewId.ToString(), Reason = "Enrollment CSV committed with capacity-based ACTIVE/WAITLISTED assignment. No invoices were created.", MetadataJson = JsonSerializer.Serialize(new { previewId = request.PreviewId, createdCount = enrollments.Count, activeCount = enrollments.Count(x => x.Status == "ACTIVE"), waitlistedCount = enrollments.Count(x => x.Status == "WAITLISTED"), state = "COMMITTED" }) }); await db.SaveChangesAsync(ct); return Results.Ok(new { data = new { request.PreviewId, createdCount = enrollments.Count, activeCount = enrollments.Count(x => x.Status == "ACTIVE"), waitlistedCount = enrollments.Count(x => x.Status == "WAITLISTED"), enrollmentIds = enrollments.Select(x => x.Id).ToArray(), state = "COMMITTED" } });
    }

    private static async Task<(byte[]? Bytes, string? Name, IResult? Error)> ReadUpload(HttpRequest request, CancellationToken ct) { var form = await request.ReadFormAsync(ct); var file = form.Files.GetFile("file"); if (file is null || file.Length == 0 || file.Length > MaxBytes || !Path.GetExtension(file.FileName).Equals(".csv", StringComparison.OrdinalIgnoreCase)) return (null, null, Error(400, "FILE_INVALID", "A non-empty CSV file up to 5 MB with .csv extension is required.")); await using var input = file.OpenReadStream(); await using var output = new MemoryStream(); await input.CopyToAsync(output, ct); return (output.ToArray(), Path.GetFileName(file.FileName).Trim(), null); }
    private static EnrollmentRow[] Parse(byte[] bytes, out List<string> errors) { errors = []; var lines = Encoding.UTF8.GetString(bytes).TrimStart('\uFEFF').Split('\n').Select(x => x.TrimEnd('\r')).Where(x => !string.IsNullOrWhiteSpace(x)).ToArray(); if (lines.Length < 2 || lines[0].ToLowerInvariant() != "studentid,courseofferingid,finalpricepiastres") { errors.Add("Header must be studentId,courseOfferingId,finalPricePiastres."); return []; } var rows = new List<EnrollmentRow>(); for (var i = 1; i < lines.Length; i++) { var c = lines[i].Split(','); if (c.Length != 3 || !Guid.TryParse(c[0], out var student) || !Guid.TryParse(c[1], out var offering) || !int.TryParse(c[2], NumberStyles.Integer, CultureInfo.InvariantCulture, out var price)) errors.Add($"Row {i + 1}: invalid enrollment values."); else rows.Add(new EnrollmentRow(student, offering, price)); } return rows.ToArray(); }
    private static SourceFileIdentity MakeSource(byte[] bytes, string name) { var now = DateTimeOffset.UtcNow; return new SourceFileIdentity(name, bytes.Length, Hash(bytes), now, now.Add(PreviewLifetime)); } private static string Hash(byte[] bytes) => Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant(); private static bool FixedHash(string a, string b) => a.Length == b.Length && CryptographicOperations.FixedTimeEquals(Encoding.UTF8.GetBytes(a), Encoding.UTF8.GetBytes(b)); private static string Key(Guid student, Guid offering) => $"{student:N}|{offering:N}"; private static bool TryScope(ClaimsPrincipal user, out Guid tenant, out Guid? branch) { var ok = Guid.TryParse(user.FindFirstValue("tenantId"), out tenant); branch = Guid.TryParse(user.FindFirstValue("branchId"), out var id) ? id : null; return ok; } private static Guid? Actor(ClaimsPrincipal user) => Guid.TryParse(user.FindFirstValue("sub"), out var id) ? id : null; private static bool CanImport(ClaimsPrincipal user) => user.IsInRole("R02_BRANCH_MANAGER") || user.IsInRole("R05_SECRETARY"); private static IResult Validation(List<string> e) => Results.ValidationProblem(new Dictionary<string, string[]> { ["file"] = e.ToArray() }); private static IResult Error(int status, string code, string message) => Results.Json(new { error = new { code, message } }, statusCode: status);
}
public sealed record EnrollmentRow(Guid StudentId, Guid OfferingId, int Price); public sealed record EnrollmentPreviewRow(int RowNumber, Guid StudentId, Guid OfferingId, int Price, string Status, string Action, IReadOnlyList<string> Errors); public sealed record StoredEnrollmentPreview(Guid PreviewId, string Hash, string State, IReadOnlyList<EnrollmentPreviewRow> Rows, SourceFileIdentity Source); public sealed record EnrollmentCommitRequest(Guid PreviewId, string PreviewHash, SourceFileIdentity? SourceFile);
